body:
Book 使用 string 管理文字，构造时验证字段；固定长度记录则由独立编码规则生成。这样既不会把 string 内部指针写到文件，也不会把没有终止零的字符数组直接当字符串读取。

下面完整头文件保存为 lesson_library.hpp，与下一节单独 main.cpp 组成程序。文件头8字节，随后每条356字节：书名128、编号128、价格分的十进制文本50、作者50。字段以零填充并保留至少一个终止零，读取时要求剩余填充也为零。本例在八位字节、文字采用约定编码的环境下使用。

~~~cpp
#pragma once
#include <algorithm>
#include <array>
#include <charconv>
#include <filesystem>
#include <fstream>
#include <stdexcept>
#include <string>
#include <system_error>
#include <utility>
#include <vector>
namespace lesson {
inline long long parseNumber(const std::string& text) {
    long long value = 0;
    const auto result = std::from_chars(text.data(), text.data() + text.size(), value);
    if (result.ec != std::errc{} || result.ptr != text.data() + text.size()
        || value < 0 || value > 100000000)
        throw std::invalid_argument("expected integer in 0..100000000");
    return value;
}
using Record = std::array<char, 356>;
inline void putField(Record& record, std::size_t offset, std::size_t capacity,
                     const std::string& text) {
    if (text.size() >= capacity || text.find('\0') != std::string::npos)
        throw std::invalid_argument("field too long or contains NUL");
    std::copy(text.begin(), text.end(), record.begin() + offset);
}
inline std::string getField(const Record& record, std::size_t offset, std::size_t capacity) {
    const auto first = record.begin() + offset;
    const auto last = first + capacity;
    const auto zero = std::find(first, last, '\0');
    if (zero == last || std::any_of(zero, last, [](char ch) { return ch != '\0'; }))
        throw std::runtime_error("invalid field padding");
    return std::string(first, zero);
}
class Book {
    std::string titleValue, idValue, authorValue;
    long long centsValue;
    static void checkText(const std::string& text, std::size_t capacity) {
        if (text.empty() || text.size() >= capacity || text.find('\0') != std::string::npos)
            throw std::invalid_argument("empty, too long or invalid text field");
    }
public:
    Book(std::string title, std::string id, long long cents, std::string author)
        : titleValue(std::move(title)), idValue(std::move(id)),
          authorValue(std::move(author)), centsValue(cents) {
        checkText(titleValue, 128);
        checkText(idValue, 128);
        checkText(authorValue, 50);
        if (centsValue < 0 || centsValue > 100000000)
            throw std::invalid_argument("price outside range");
    }
    const std::string& title() const { return titleValue; }
    const std::string& id() const { return idValue; }
    const std::string& author() const { return authorValue; }
    long long cents() const { return centsValue; }
    Record encode() const {
        Record record{};
        putField(record, 0, 128, titleValue);
        putField(record, 128, 128, idValue);
        putField(record, 256, 50, std::to_string(centsValue));
        putField(record, 306, 50, authorValue);
        return record;
    }
    static Book decode(const Record& record) {
        return Book(getField(record, 0, 128), getField(record, 128, 128),
                    parseNumber(getField(record, 256, 50)), getField(record, 306, 50));
    }
};
class Library {
    std::filesystem::path path;
    std::vector<Book> books;
    static constexpr std::array<char, 8> magic{'B','K','2','0','V','1','\n','\0'};
    std::vector<Book> load() const {
        if (!std::filesystem::exists(path)) return {};
        std::ifstream input(path, std::ios::binary);
        if (!input) throw std::runtime_error("cannot open library");
        std::array<char, 8> header{};
        input.read(header.data(), static_cast<std::streamsize>(header.size()));
        if (!input || header != magic) throw std::runtime_error("wrong library format");
        std::vector<Book> result;
        for (;;) {
            Record record{};
            input.read(record.data(), static_cast<std::streamsize>(record.size()));
            const std::streamsize count = input.gcount();
            if (input.bad()) throw std::runtime_error("library read failed");
            if (count == 0 && input.eof()) break;
            if (count != static_cast<std::streamsize>(record.size()) || !input)
                throw std::runtime_error("truncated library record");
            if (result.size() >= 10000) throw std::runtime_error("too many books");
            Book book = Book::decode(record);
            if (std::any_of(result.begin(), result.end(), [&](const Book& old) {
                    return old.id() == book.id();
                })) throw std::runtime_error("duplicate stored id");
            result.push_back(std::move(book));
        }
        return result;
    }
    void save(const std::vector<Book>& next) const {
        auto temporary = path;
        temporary += ".tmp";
        std::ofstream output(temporary, std::ios::binary | std::ios::trunc);
        if (!output) throw std::runtime_error("cannot open temporary library");
        output.write(magic.data(), static_cast<std::streamsize>(magic.size()));
        for (const Book& book : next) {
            const Record record = book.encode();
            output.write(record.data(), static_cast<std::streamsize>(record.size()));
            if (!output) throw std::runtime_error("library write failed");
        }
        output.close();
        if (!output) throw std::runtime_error("library close failed");
        std::filesystem::rename(temporary, path);
    }
public:
    explicit Library(std::filesystem::path file) : path(std::move(file)), books(load()) {}
    const std::vector<Book>& records() const { return books; }
    void add(Book book) {
        if (books.size() >= 10000) throw std::runtime_error("library is full");
        if (std::any_of(books.begin(), books.end(), [&](const Book& old) {
                return old.id() == book.id();
            })) throw std::invalid_argument("duplicate id");
        auto next = books;
        next.push_back(std::move(book));
        save(next);
        books.swap(next);
    }
    bool eraseById(const std::string& id) {
        if (std::none_of(books.begin(), books.end(), [&](const Book& book) {
                return book.id() == id;
            })) return false;
        auto next = books;
        next.erase(std::remove_if(next.begin(), next.end(), [&](const Book& book) {
            return book.id() == id;
        }), next.end());
        save(next);
        books.swap(next);
        return true;
    }
};
}
~~~

load 遇到零个剩余字节且正常末尾才结束；读到半条就拒绝，避免显示旧缓冲。decode 重新走 Book 构造验证，文件里的文字和价格不会因为来自磁盘就被默认信任。

save 先写同目录的专用 .tmp，再检查 close，最后 rename 替换正式路径；没有先清空正式文件。要求这两条路径由本练习单独管理，不存在别的进程同时写入或把它们改成相互链接。替换失败会抛出，内存副本尚未提交，临时文件可能保留供检查。

Book 没有公开可写字符指针，读取成员用 const 引用；引用仍依赖对象寿命，不应跨越集合修改保存。构造验证使有效对象保持字段条件，也避免随意逐字段设置到一半就被当成完整记录使用。

本例不承诺断电后文件一定持久保存，也不处理多个进程同时编辑。文件格式带版本头、字段明确、失败可见，已经比直接 write 整个类对象更容易理解和验证。

主程序只负责菜单、收集输入和显示结果。它包含上一节完整 lesson_library.hpp，不再把文件定位散落在各个菜单分支里。所有交互使用 getline，避免数字提取后残留换行影响下一条书名。

~~~cpp
#include "lesson_library.hpp"
#include <iomanip>
#include <iostream>
void showPage(const std::vector<lesson::Book>& books, std::size_t page) {
    if (books.empty()) { std::cout << "no books\n"; return; }
    const std::size_t pages = (books.size() + 19) / 20;
    if (page < 1 || page > pages) throw std::out_of_range("invalid page");
    const std::size_t first = (page - 1) * 20;
    const std::size_t last = std::min(first + 20, books.size());
    std::cout << "page " << page << '/' << pages << ", total=" << books.size() << '\n';
    for (std::size_t i = first; i < last; ++i) {
        const auto& book = books[i];
        std::cout << i + 1 << " | " << book.id() << " | " << book.title() << " | "
                  << book.cents() / 100 << '.' << std::setw(2) << std::setfill('0')
                  << book.cents() % 100 << std::setfill(' ') << " | " << book.author() << '\n';
    }
}
int main() {
    try {
        lesson::Library library("lesson-books-v2.dat");
        for (;;) {
            std::cout << "1 add, 2 show page, 3 delete by id, 0 exit\n";
            std::string command;
            if (!std::getline(std::cin, command) || command == "0") break;
            try {
                if (command == "1") {
                    std::string title, id, price, author;
                    std::cout << "title, id, price in cents, author (one per line):\n";
                    if (!std::getline(std::cin, title) || !std::getline(std::cin, id)
                        || !std::getline(std::cin, price) || !std::getline(std::cin, author)) break;
                    library.add(lesson::Book(title, id, lesson::parseNumber(price), author));
                    std::cout << "added\n";
                } else if (command == "2") {
                    std::string page;
                    std::cout << "page number:\n";
                    if (!std::getline(std::cin, page)) break;
                    const auto number = lesson::parseNumber(page);
                    if (number == 0) throw std::out_of_range("page starts at 1");
                    const auto& books = library.records();
                    if (books.empty()) {
                        showPage(books, 1);
                    } else {
                        const auto pages = (books.size() + 19) / 20;
                        if (number > static_cast<long long>(pages))
                            throw std::out_of_range("invalid page");
                        // 先确认原页号有效，再转成能表示该页号的索引类型。
                        showPage(books, static_cast<std::size_t>(number));
                    }
                } else if (command == "3") {
                    std::string id;
                    std::cout << "id to delete:\n";
                    if (!std::getline(std::cin, id)) break;
                    std::cout << (library.eraseById(id) ? "deleted" : "not found") << '\n';
                } else std::cout << "unknown command\n";
            } catch (const std::exception& e) {
                std::cout << "operation failed: " << e.what() << '\n';
            }
        }
    } catch (const std::exception& e) {
        std::cerr << "startup failed: " << e.what() << '\n';
        return 1;
    }
}
~~~

两层异常处理有不同责任：启动时文件格式错误不能进入一个假空集合；菜单中的非法价格则只让当前动作失败，再返回主菜单。输入四字段途中遇到 EOF，会退出循环，不把缺失字段拼成半条记录保存。

在已有 C++20 控制台项目中，把公共头与这一个 main.cpp 放在同一可见目录构建。使用独立工作目录，确认 lesson-books-v2.dat 与 .tmp 都属于这次练习，原旧教材 book.dat 不会被本例自动迁移。这里提供操作步骤与逻辑推导，没有代替读者运行本机文件程序。

显示空集合时给出 no books；非空集合页码从1开始。页号先保持为解析得到的 long long，与当前实际页数比较，确认有效后才转成 size_t。集合最多10000条，每页20条，所以合法页号至多500；这样不依赖 size_t 在某个实现上恰好足够宽，也不会让一个很大的页号先截短、绕回成另一个有效页号。主循环不递归调用自己，完成任何一个动作后自然回到菜单，选择0或输入结束才离开。
